    [Theory]
    [MemberData(nameof(Cases))]
    public void StyleAssociationsMatchWordWithoutMutatingSource(string name, string styles, string numbering, string document, string[] expected)
    {
        using var stream = new MemoryStream();
        using var doc = WordprocessingDocument.Create(stream, WordprocessingDocumentType.Document);
        var main = doc.AddMainDocumentPart();
        main.AddNewPart<StyleDefinitionsPart>().Styles = new Styles(styles);
        main.AddNewPart<NumberingDefinitionsPart>().Numbering = new Numbering(numbering);
        main.Document = new Document(document);
        _ = main.StyleDefinitionsPart!.Styles.Descendants().ToArray();
        _ = main.NumberingDefinitionsPart!.Numbering.Descendants().ToArray();
        _ = main.Document.Descendants().ToArray();
        var beforeStyles = main.StyleDefinitionsPart.Styles.OuterXml;
        var beforeNumbering = main.NumberingDefinitionsPart.Numbering.OuterXml;
        var beforeDocument = main.Document.OuterXml;
        foreach (var source in new[] { doc })
        {
            DxpITextVisitor[] visitors = [new DxpMarkdownVisitor(DxpMarkdownVisitorConfig.CreatePlainConfig()),
                new DxpHtmlVisitor(DxpHtmlVisitorConfig.CreatePlainConfig()),
                new DxpPlainTextVisitor(DxpPlainTextVisitorConfig.CreateAcceptConfig()),
                new DxpHtmlVisitor(DxpHtmlVisitorConfig.CreateRichConfig()),
                new DxpMarkdownVisitor(DxpMarkdownVisitorConfig.CreateRichConfig())];
            foreach (var visitor in visitors)
            {
                var output = DxpExport.ExportToString(source, visitor);
                if (visitor is DxpHtmlVisitor or DxpMarkdownVisitor) output = new HtmlParser().ParseDocument(output).Body!.TextContent;
                var actual = Regex.Matches(output, @"(?:BEGIN|CHILD)\d+END").Select(m => m.Value).ToArray();
                Assert.True(expected.SequenceEqual(actual), name + " " + "source" + " " + visitor.GetType().Name + " expected=" + string.Join(",", expected) + " actual=" + string.Join(",", actual));
                Assert.Equal(3, Regex.Matches(output, @"Item[0-2]").Count);
            }
        }
        Assert.Equal(beforeStyles, main.StyleDefinitionsPart.Styles.OuterXml);
        Assert.Equal(beforeNumbering, main.NumberingDefinitionsPart.Numbering.OuterXml);
        Assert.Equal(beforeDocument, main.Document.OuterXml);
    }
